// Offline support. The file list + version come from precache.js (generated by tools/gen-precache.mjs).
importScripts('./precache.js');
const CACHE = 'thrive-' + self.PRECACHE_VERSION;

self.addEventListener('install', (e) => {
  e.waitUntil((async () => {
    const c = await caches.open(CACHE);
    // App shell first (must succeed), then images in the background-ish (best effort).
    await c.addAll(self.PRECACHE_SHELL);
    await Promise.allSettled(self.PRECACHE_ASSETS.map((u) => c.add(u)));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('thrive-') && k !== CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return; // YouTube etc. go straight to the network
  e.respondWith((async () => {
    const c = await caches.open(CACHE);
    const hit = await c.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      const res = await fetch(req);
      if (res.ok) c.put(req, res.clone());
      return res;
    } catch (err) {
      if (req.mode === 'navigate') return (await c.match('./index.html')) || Response.error();
      throw err;
    }
  })());
});
